// === Tab: mySketch ===
//Made by 16384 - Feb. 2020

let num = 500;
let pos = [];
let vel = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	for (let i = 0; i < num; i++) {
		pos[i] = createVector(width / 2, height / 2);
		vel[i] = createVector(0, 0);
	}
	colorMode(HSB);
}

function draw() {
	for (let i = 0; i < pos.length; i++) {
		pos[i].add(vel[i]);

		let rotation = random(TWO_PI);
		vel[i].x += cos(rotation) * 0.1;
		vel[i].y += sin(rotation) * 0.1;

		if (pos[i].x < 0 || pos[i].x > width || pos[i].y < 0 || pos[i].y > height) {
			vel[i].mult(0);
		}

		stroke(0,86,123);
		stroke(frameCount / 2 % 255, 255, 255);
		line(pos[i].x, pos[i].y, pos[i].x + vel[i].x * 2, pos[i].y + vel[i].y * 2);
	}
}

function keyPressed() {
	if (key == 'r') {
		pos = [];
		vel = [];
		for (let i = 0; i < num; i++) {
			pos[i] = createVector(width / 2, height / 2);
			vel[i] = createVector(0, 0);
		}
		background(0);
	}
}

